pub fn addAlgebraicLoopsModelInfoStateSets(mut inSets: Arc<metamodelica::List<SimCode::StateSet>>, mut inModelInfo: SimCode::ModelInfo) -> Result<(Arc<metamodelica::List<SimCode::StateSet>>, SimCode::ModelInfo, Arc<metamodelica::List<Arc<SimCode::JacobianMatrix>>>, Arc<metamodelica::List<Arc<SimCode::JacobianMatrix>>>)> {
    let mut outSets: Arc<metamodelica::List<SimCode::StateSet>> = metamodelica::nil();
    let mut modelInfo: SimCode::ModelInfo = inModelInfo.clone();
    let mut outSymJacs: Arc<metamodelica::List<Arc<SimCode::JacobianMatrix>>> = metamodelica::nil();
    let mut outSymJacsInternal: Arc<metamodelica::List<Arc<SimCode::JacobianMatrix>>> = metamodelica::nil();
    let mut symJac: Arc<SimCode::JacobianMatrix>;
    let mut tmpSymJacs: Arc<metamodelica::List<Arc<SimCode::JacobianMatrix>>> = metamodelica::nil();
    for mut set in &*inSets.clone() {
        let mut set = set.clone();
        let (__pa0, __pa1, __pa2) = ::match_deref::match_deref! { match &(addAlgebraicLoopsModelInfoSymJacs(list![set.jacobianMatrix.clone()], modelInfo.clone())) {
            (Deref @ metamodelica::List::Cons { head: __pa0, tail: Deref @ metamodelica::List::Nil }, __pa1, __pa2) => (__pa0.clone(), __pa1.clone(), __pa2.clone()),
            _ => bail!("pattern mismatch"),
        } };
        symJac = __pa0.clone();
        modelInfo = __pa1.clone();
        tmpSymJacs = __pa2.clone();
        outSymJacsInternal = listAppend(tmpSymJacs.clone(), outSymJacsInternal.clone());
        set.jacobianMatrix = symJac.clone();
        outSymJacs = cons(symJac.clone(), outSymJacs.clone());
        outSets = cons(set.clone(), outSets.clone());
    }
    outSets = outSets.clone().reverse();
    outSymJacs = outSymJacs.clone().reverse();
    outSymJacsInternal = outSymJacsInternal.clone().reverse();
    Ok((outSets, modelInfo, outSymJacs, outSymJacsInternal))
}

fn addAlgebraicLoopsClockPartitions(mut inColockPartition: Arc<metamodelica::List<SimCode::ClockedPartition>>, mut inModelInfo: SimCode::ModelInfo) -> Result<(Arc<metamodelica::List<SimCode::ClockedPartition>>, SimCode::ModelInfo, Arc<metamodelica::List<Arc<SimCode::JacobianMatrix>>>)> {
    let mut outColockPartition: Arc<metamodelica::List<SimCode::ClockedPartition>> = metamodelica::nil();
    let mut modelInfo: SimCode::ModelInfo = inModelInfo.clone();
    let mut outSymJacs: Arc<metamodelica::List<Arc<SimCode::JacobianMatrix>>> = metamodelica::nil();
    let mut subPartitionTmp: SimCode::SubPartition;
    let mut clockPartitionTmp: SimCode::ClockedPartition;
    let mut subPartitionsTmp: Arc<metamodelica::List<SimCode::SubPartition>> = metamodelica::nil();
    let mut equations: Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>> = metamodelica::nil();
    let mut tmpJacs: Arc<metamodelica::List<Arc<SimCode::JacobianMatrix>>> = metamodelica::nil();
    let mut clockIndex: i32 = 0;
    for mut clockPartion in &*inColockPartition.clone() {
        let mut clockPartion = clockPartion.clone();
        subPartitionsTmp = metamodelica::nil();
        for mut subPartion in &*clockPartion.subPartitions.clone() {
            let mut subPartion = subPartion.clone();
            clockIndex = clockIndex.clone() + 1;
            (equations, modelInfo, tmpJacs) = addAlgebraicLoopsModelInfo(subPartion.equations.clone(), modelInfo.clone())?;
            tmpJacs = {
        let mut __acc: Arc<metamodelica::List<Arc<SimCode::JacobianMatrix>>> = metamodelica::nil();
        for mut a in (tmpJacs.clone()).into_iter().cloned() {
            let __x = rewriteJacPartIdx(a.clone(), clockIndex.clone());
            __acc = cons(__x, __acc);
        }
        __acc.reverse()
    };
            outSymJacs = listAppend(tmpJacs.clone(), outSymJacs.clone());
            subPartitionTmp = SimCode::SubPartition { vars: subPartion.vars.clone(), equations: equations.clone(), removedEquations: subPartion.removedEquations.clone(), subClock: subPartion.subClock.clone(), holdEvents: subPartion.holdEvents.clone() };
            subPartitionsTmp = cons(subPartitionTmp.clone(), subPartitionsTmp.clone());
        }
        clockPartitionTmp = SimCode::ClockedPartition { baseClock: clockPartion.baseClock.clone(), subPartitions: subPartitionsTmp.clone().reverse() };
        outColockPartition = cons(clockPartitionTmp.clone(), outColockPartition.clone());
    }
    outColockPartition = outColockPartition.clone().reverse();
    Ok((outColockPartition, modelInfo, outSymJacs))
}

fn rewriteJacPartIdx(mut inJac: Arc<SimCode::JacobianMatrix>, mut index: i32) -> Arc<SimCode::JacobianMatrix> {
    let mut outJac: Arc<SimCode::JacobianMatrix> = inJac.clone();
    assign_field!(outJac.partitionIndex = index.clone());
    outJac
}

pub fn jacobianColumnsAreEmpty(mut columns: Arc<metamodelica::List<Arc<SimCode::JacobianColumn>>>) -> bool {
    let mut b: bool = true;
    for mut col in &*columns.clone() {
        let mut col = col.clone();
        if !(col.columnEqns.clone().is_empty() && col.constantEqns.clone().is_empty()) {
            b = false;
            return b;
        }
    }
    b
}

