fn createEquationsForSystems1(mut inSyst: Arc<BackendDAE::EqSystem>, mut inArg: CreateEquationsForSystemsArg, mut inFold: CreateEquationsForSystemsFold) -> Result<CreateEquationsForSystemsFold> {
    let mut outFold: CreateEquationsForSystemsFold;
    outFold = (::match_deref::match_deref! { match &(inSyst.matching.clone()) {
        Deref @ BackendDAE::Matching::MATCHING { comps, ass1, .. } => {
            let mut odeEquations1: Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>> = metamodelica::nil();
            let mut algebraicEquations1: Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>> = metamodelica::nil();
            let mut allEquations1: Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>> = metamodelica::nil();
            let mut syst: Arc<BackendDAE::EqSystem>;
            let mut odeEquations: Arc<metamodelica::List<Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>>>> = metamodelica::nil();
            let mut algebraicEquations: Arc<metamodelica::List<Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>>>> = metamodelica::nil();
            let mut allEquations: Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>> = metamodelica::nil();
            let mut equationsForZeroCrossings: Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>> = metamodelica::nil();
            let mut equationsForZeroCrossings1: Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>> = metamodelica::nil();
            let mut uniqueEqIndex: i32 = 0;
            let mut sccOffset: i32 = 0;
            let mut stateeqnsmark: metamodelica::Array<i32>;
            let mut zceqnsmarks: metamodelica::Array<i32>;
            let mut tempvars: Arc<metamodelica::List<SimCodeVar::SimVar>> = metamodelica::nil();
            let mut funcs; // TODO: local with unresolved type
            let mut eqSccMapping: Arc<metamodelica::List<(i32, i32)>> = metamodelica::nil();
            let mut eqBackendSimCodeMapping: Arc<metamodelica::List<(i32, i32)>> = metamodelica::nil();
            let mut backendMapping: SimCode::BackendMapping = SimCode::BackendMapping::NO_MAPPING;
            let mut zeroCrossings: Arc<metamodelica::List<BackendDAE::ZeroCrossing>> = metamodelica::nil();
            let mut shared: Arc<BackendDAE::Shared>;
            let mut createAlgebraicEquations: bool = false;
            if Flags::isSet(Flags::BLT_MATRIX_DUMP.clone())? {
                BackendDump::dumpEqSystemBLTmatrixHTML(inSyst.clone())?;
            }
            (shared, zeroCrossings, createAlgebraicEquations) = inArg.clone();
            (uniqueEqIndex, odeEquations, algebraicEquations, allEquations, equationsForZeroCrossings, tempvars, eqSccMapping, eqBackendSimCodeMapping, backendMapping, sccOffset) = inFold.clone();
            funcs = BackendDAEUtil::getFunctions(shared.clone())?;
            (syst, _, _) = BackendDAEUtil::getAdjacencyMatrixfromOption(inSyst.clone(), crate::BackendDAE::IndexType::ABSOLUTE, Some(funcs.clone()), BackendDAEUtil::isInitializationDAE(shared.clone()))?;
            stateeqnsmark = arrayCreate(BackendDAEUtil::equationArraySizeDAE(syst.clone()), 0);
            zceqnsmarks = arrayCreate(BackendDAEUtil::equationArraySizeDAE(syst.clone()), 0);
            stateeqnsmark = BackendDAEUtil::markStateEquations(syst.clone(), stateeqnsmark.clone(), ass1.clone())?;
            zceqnsmarks = BackendDAEUtil::markZeroCrossingEquations(syst.clone(), zeroCrossings.clone(), zceqnsmarks.clone(), ass1.clone())?;
            (odeEquations1, algebraicEquations1, allEquations1, equationsForZeroCrossings1, uniqueEqIndex, tempvars, eqSccMapping, eqBackendSimCodeMapping, backendMapping) = createEquationsForSystem(stateeqnsmark.clone(), zceqnsmarks.clone(), syst.clone(), shared.clone(), comps.clone(), uniqueEqIndex.clone(), tempvars.clone(), sccOffset.clone(), eqSccMapping.clone(), eqBackendSimCodeMapping.clone(), backendMapping.clone(), createAlgebraicEquations.clone());
            GCExt::free(stateeqnsmark.clone());
            GCExt::free(zceqnsmarks.clone());
            odeEquations = List::consOnTrue(!(odeEquations1.clone().is_empty()), odeEquations1.clone(), odeEquations.clone());
            algebraicEquations = List::consOnTrue(!(algebraicEquations1.clone().is_empty()), algebraicEquations1.clone(), algebraicEquations.clone());
            allEquations = List::append_reverse(allEquations1.clone(), allEquations.clone());
            equationsForZeroCrossings = List::append_reverse(equationsForZeroCrossings1.clone(), equationsForZeroCrossings.clone());
            (uniqueEqIndex.clone(), odeEquations.clone(), algebraicEquations.clone(), allEquations.clone(), equationsForZeroCrossings.clone(), tempvars.clone(), eqSccMapping.clone(), eqBackendSimCodeMapping.clone(), backendMapping.clone(), (comps.clone().len() as i32) + sccOffset.clone())
        },
        _ => {
            inFold.clone()
        },
        _ => unreachable!("match_deref! exhaustiveness placeholder"),
    } });
    Ok(outFold)
}

