pub fn getSimCodeDAEModeDataEqns(mut inOptDaeMode: Option<SimCode::DaeModeData>) -> Result<Arc<metamodelica::List<Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>>>>> {
    let mut daeEquations: Arc<metamodelica::List<Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>>>> = metamodelica::nil();
    let mut daeModeData: SimCode::DaeModeData;
    if isSome(inOptDaeMode.clone()) {
        daeModeData = Util::getOption(inOptDaeMode.clone())?;
        daeEquations = daeModeData.daeEquations.clone();
    } else {
        daeEquations = metamodelica::nil();
    }
    Ok(daeEquations)
}

pub fn sortSimVarsAndWriteIndex(mut inSimVar: Arc<metamodelica::List<SimCodeVar::SimVar>>, mut crefToSimVarHT: (metamodelica::Array<Arc<metamodelica::List<(Arc<DAE::ComponentRef>, i32)>>>, (i32, i32, metamodelica::Array<Option<(Arc<DAE::ComponentRef>, SimCodeVar::SimVar)>>), i32, (HashTableCrefSimVar::FuncHashCref, HashTableCrefSimVar::FuncCrefEqual, HashTableCrefSimVar::FuncCrefStr, HashTableCrefSimVar::FuncExpStr))) -> Result<Arc<metamodelica::List<SimCodeVar::SimVar>>> {
    let mut outSimVar: Arc<metamodelica::List<SimCodeVar::SimVar>> = metamodelica::nil();
    let mut crefs: Arc<metamodelica::List<Arc<DAE::ComponentRef>>> = metamodelica::nil();
    let mut sorted: Arc<metamodelica::List<SimCodeVar::SimVar>> = metamodelica::nil();
    crefs = List::map(inSimVar.clone(), Arc::new(fnptr!(getSimVarCompRef, SimCodeVar::SimVar)));
    sorted = getSimVars2Crefs(crefs.clone(), crefToSimVarHT.clone());
    sorted = List::sort(sorted.clone(), Arc::new(compareVarIndexGt))?;
    (outSimVar, _) = rewriteIndex(sorted.clone(), 0);
    Ok(outSimVar)
}

