fn replaceIFBrancheswithoutVar(mut inExp: Arc<DAE::Exp>, mut inTpl: (Arc<DAE::Exp>, Arc<DAE::Exp>)) -> Result<(Arc<DAE::Exp>, (Arc<DAE::Exp>, Arc<DAE::Exp>))> {
    let mut outExp: Arc<DAE::Exp>;
    let mut outTpl: (Arc<DAE::Exp>, Arc<DAE::Exp>);
    (outExp, outTpl) = (::match_deref::match_deref! { match &((inExp.clone(), inTpl.clone())) {
        (Deref @ DAE::Exp::IFEXP { expCond: cond, expThen: e1, expElse: e2 }, (crexp, exp)) => {
            let mut b1: bool = false;
            let mut b2: bool = false;
            let mut e1 = (*e1).clone();
            let mut e2 = (*e2).clone();
            b1 = Expression::expContains(e1.clone(), crexp.clone())?;
            e1 = if (b1.clone()) {e1.clone()} else {exp.clone()};
            b2 = Expression::expContains(e2.clone(), crexp.clone())?;
            e2 = if (b2.clone()) {e2.clone()} else {exp.clone()};
            (if (b1.clone() && b2.clone()) {inExp.clone()} else {Arc::new(DAE::Exp::IFEXP { expCond: cond.clone(), expThen: e1.clone(), expElse: e2.clone() })}, inTpl.clone())
        },
        _ => {
            (inExp.clone(), inTpl.clone())
        },
        _ => unreachable!("match_deref! exhaustiveness placeholder"),
    } });
    Ok((outExp, outTpl))
}

fn solveAlgorithmInverse(mut inStmts: Arc<metamodelica::List<Arc<DAE::Statement>>>, mut inSolveFor: Arc<metamodelica::List<BackendDAE::Var>>) -> Result<Arc<metamodelica::List<Arc<DAE::Statement>>>> {
    let mut outStmts: Arc<metamodelica::List<Arc<DAE::Statement>>> = metamodelica::nil();
    outStmts = (::match_deref::match_deref! { match &((inStmts.clone(), inSolveFor.clone())) {
        (Deref @ metamodelica::List::Cons { head: Deref @ DAE::Statement::STMT_ASSIGN { source: source1, exp: e12, exp1: e11, .. }, tail: Deref @ metamodelica::List::Nil }, Deref @ metamodelica::List::Cons { head: v1 @ BackendDAE::Var { varName: cr1, .. }, tail: Deref @ metamodelica::List::Nil }) => {
            let mut varexp1: Arc<DAE::Exp>;
            let mut solvedExp1: Arc<DAE::Exp>;
            let mut tp1: Arc<DAE::Type> = Arc::new(DAE::Type::T_NORETCALL);
            let mut asserts: Arc<metamodelica::List<Arc<DAE::Statement>>> = metamodelica::nil();
            let mut source1 = (*source1).clone();
            let mut cr1 = (*cr1).clone();
            varexp1 = Expression::crefExp(cr1.clone())?;
            varexp1 = if (BackendVariable::isStateVar(v1.clone())) {Expression::expDer(varexp1.clone())} else {varexp1.clone()};
            (solvedExp1, asserts) = ExpressionSolve::solve(e11.clone(), e12.clone(), varexp1.clone(), None)?;
            cr1 = if (BackendVariable::isStateVar(v1.clone())) {ComponentReference::crefPrefixDer(cr1.clone())} else {cr1.clone()};
            source1 = ElementSource::addSymbolicTransformationSolve(true, source1.clone(), cr1.clone(), e11.clone(), e12.clone(), solvedExp1.clone(), asserts.clone())?;
            tp1 = Expression::r#typeof(varexp1.clone())?;
            list![Arc::new(DAE::Statement::STMT_ASSIGN { type_: tp1.clone(), exp1: varexp1.clone(), exp: solvedExp1.clone(), source: source1.clone() })]
        },
        (Deref @ metamodelica::List::Cons { head: Deref @ DAE::Statement::STMT_ASSIGN { source: source1, exp: e12, exp1: e11, .. }, tail: Deref @ metamodelica::List::Cons { head: Deref @ DAE::Statement::STMT_ASSIGN { source: source2, exp: e22, exp1: e21, .. }, tail: Deref @ metamodelica::List::Nil } }, Deref @ metamodelica::List::Cons { head: v1 @ BackendDAE::Var { varName: cr1, .. }, tail: Deref @ metamodelica::List::Cons { head: v2 @ BackendDAE::Var { varName: cr2, .. }, tail: Deref @ metamodelica::List::Nil } }) => {
            let mut varexp1: Arc<DAE::Exp>;
            let mut solvedExp1: Arc<DAE::Exp>;
            let mut tp1: Arc<DAE::Type> = Arc::new(DAE::Type::T_NORETCALL);
            let mut varexp2: Arc<DAE::Exp>;
            let mut solvedExp2: Arc<DAE::Exp>;
            let mut tp2: Arc<DAE::Type> = Arc::new(DAE::Type::T_NORETCALL);
            let mut asserts: Arc<metamodelica::List<Arc<DAE::Statement>>> = metamodelica::nil();
            let mut source1 = (*source1).clone();
            let mut source2 = (*source2).clone();
            let mut cr1 = (*cr1).clone();
            let mut cr2 = (*cr2).clone();
            let false = (Expression::expHasCref(e12.clone(), cr2.clone())?) else { bail!("pattern mismatch") };
            let false = (Expression::expHasCref(e22.clone(), cr1.clone())?) else { bail!("pattern mismatch") };
            varexp1 = Expression::crefExp(cr1.clone())?;
            varexp1 = if (BackendVariable::isStateVar(v1.clone())) {Expression::expDer(varexp1.clone())} else {varexp1.clone()};
            (solvedExp1, asserts) = ExpressionSolve::solve(e11.clone(), e12.clone(), varexp1.clone(), None)?;
            cr1 = if (BackendVariable::isStateVar(v1.clone())) {ComponentReference::crefPrefixDer(cr1.clone())} else {cr1.clone()};
            source1 = ElementSource::addSymbolicTransformationSolve(true, source1.clone(), cr1.clone(), e11.clone(), e12.clone(), solvedExp1.clone(), asserts.clone())?;
            tp1 = Expression::r#typeof(varexp1.clone())?;
            varexp2 = Expression::crefExp(cr2.clone())?;
            varexp2 = if (BackendVariable::isStateVar(v2.clone())) {Expression::expDer(varexp2.clone())} else {varexp2.clone()};
            (solvedExp2, asserts) = ExpressionSolve::solve(e21.clone(), e22.clone(), varexp2.clone(), None)?;
            cr2 = if (BackendVariable::isStateVar(v2.clone())) {ComponentReference::crefPrefixDer(cr2.clone())} else {cr2.clone()};
            source2 = ElementSource::addSymbolicTransformationSolve(true, source2.clone(), cr2.clone(), e21.clone(), e22.clone(), solvedExp2.clone(), asserts.clone())?;
            tp2 = Expression::r#typeof(varexp2.clone())?;
            list![Arc::new(DAE::Statement::STMT_ASSIGN { type_: tp1.clone(), exp1: varexp1.clone(), exp: solvedExp1.clone(), source: source1.clone() }), Arc::new(DAE::Statement::STMT_ASSIGN { type_: tp2.clone(), exp1: varexp2.clone(), exp: solvedExp2.clone(), source: source2.clone() })]
        },
        _ => bail!("match: no arm matched"),
    } });
    Ok(outStmts)
}

