pub fn createInitialEquations(mut inInitDAE: Arc<BackendDAE::BackendDAE>, mut iuniqueEqIndex: i32, mut itempvars: Arc<metamodelica::List<SimCodeVar::SimVar>>) -> Result<(Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>>, i32, Arc<metamodelica::List<SimCodeVar::SimVar>>)> {
    let mut outInitialEqns: Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>> = metamodelica::nil();
    let mut ouniqueEqIndex: i32 = iuniqueEqIndex.clone();
    let mut otempvars: Arc<metamodelica::List<SimCodeVar::SimVar>> = itempvars.clone();
    let mut removedEqs: Arc<ExpandableArray::ExpandableArray<Arc<BackendDAE::Equation>>>;
    let mut tempvars: Arc<metamodelica::List<SimCodeVar::SimVar>> = metamodelica::nil();
    let mut uniqueEqIndex: i32 = 0;
    let mut allEquations: Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>> = metamodelica::nil();
    let mut knownVarEquations: Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>> = metamodelica::nil();
    let mut solvedEquations: Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>> = metamodelica::nil();
    let mut removedEquations: Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>> = metamodelica::nil();
    let mut aliasEquations: Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>> = metamodelica::nil();
    let mut systs: Arc<metamodelica::List<Arc<BackendDAE::EqSystem>>> = metamodelica::nil();
    let mut shared: Arc<BackendDAE::Shared>;
    let mut globalKnownVars: BackendDAE::Variables;
    let mut aliasVars: BackendDAE::Variables;
    let (__pa0, __pa3, __pa1, __pa2) = ::match_deref::match_deref! { match &(inInitDAE.clone()) {
        Deref @ DAE { UNIQUEIO: __pa0, derivativeNamePrefix: __pa3 @ BackendDAE::Shared { aliasVars: __pa1, globalKnownVars: __pa2, .. }, .. } => (__pa0.clone(), __pa3.clone(), __pa1.clone(), __pa2.clone()),
        _ => bail!("pattern mismatch"),
    } };
    systs = __pa0.clone();
    aliasVars = __pa1.clone();
    globalKnownVars = __pa2.clone();
    shared = __pa3.clone();
    removedEqs = BackendDAEUtil::collapseRemovedEqs(inInitDAE.clone())?;
    (uniqueEqIndex, knownVarEquations) = BackendVariable::traverseBackendDAEVars(globalKnownVars.clone(), Arc::new(traverseKnVarsToSimEqSystem), (iuniqueEqIndex.clone(), metamodelica::nil()))?;
    (uniqueEqIndex, _, _, _, solvedEquations, _, tempvars, _, _, _, _) = createEquationsForSystems(systs.clone(), shared.clone(), uniqueEqIndex.clone(), metamodelica::nil(), itempvars.clone(), 0, crate::SimCode::BackendMapping::NO_MAPPING, true)?;
    (uniqueEqIndex, removedEquations) = BackendEquation::traverseEquationArray(removedEqs.clone(), Arc::new(traversedlowEqToSimEqSystem), (uniqueEqIndex.clone(), metamodelica::nil()))?;
    (uniqueEqIndex, aliasEquations) = BackendVariable::traverseBackendDAEVars(aliasVars.clone(), Arc::new(traverseAliasVarsToSimEqSystem), (uniqueEqIndex.clone(), metamodelica::nil()))?;
    allEquations = Dangerous::listReverseInPlace(aliasEquations.clone());
    allEquations = listAppend(removedEquations.clone(), allEquations.clone());
    allEquations = List::append_reverse(solvedEquations.clone(), allEquations.clone());
    allEquations = listAppend(knownVarEquations.clone(), allEquations.clone());
    outInitialEqns = allEquations.clone();
    ouniqueEqIndex = uniqueEqIndex.clone();
    otempvars = tempvars.clone();
    Ok((outInitialEqns, ouniqueEqIndex, otempvars))
}

