fn dumpJacobianMatrix(mut jacOpt: Option<Arc<SimCode::JacobianMatrix>>) -> Result<()> {
    let _ = (::match_deref::match_deref! { match &(jacOpt.clone()) {
        Some(jac) => {
            let mut idx: i32 = 0;
            let mut cols: Arc<metamodelica::List<Arc<SimCode::JacobianColumn>>> = metamodelica::nil();
            let mut colEqs: Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>> = metamodelica::nil();
            let mut colVars: Arc<metamodelica::List<SimCodeVar::SimVar>> = metamodelica::nil();
            let (__pa0, __pa1) = ::match_deref::match_deref! { match &(jac.clone()) {
                Deref @ SimCode::JacobianMatrix { jacobianIndex: __pa0, columns: __pa1, .. } => (__pa0.clone(), __pa1.clone()),
                _ => bail!("pattern mismatch"),
            } };
            idx = __pa0.clone();
            cols = __pa1.clone();
            colEqs = List::flatten({
        let mut __acc: Arc<metamodelica::List<Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>>>> = metamodelica::nil();
        for mut a in (cols.clone()).into_iter().cloned() {
            let __x = a.columnEqns.clone();
            __acc = cons(__x, __acc);
        }
        __acc.reverse()
    });
            colVars = List::flatten({
        let mut __acc: Arc<metamodelica::List<Arc<metamodelica::List<SimCodeVar::SimVar>>>> = metamodelica::nil();
        for mut a in (cols.clone()).into_iter().cloned() {
            let __x = a.columnVars.clone();
            __acc = cons(__x, __acc);
        }
        __acc.reverse()
    });
            println!("{}", ({ let mut __mm_s = String::new(); __mm_s.push_str(&*literal!("\tJacobian idx: ")); __mm_s.push_str(&*intString(idx.clone())); __mm_s.push_str(&*literal!("\n\t")); ArcStr::from(__mm_s) }).clone());
            dumpSimEqSystemLst(colEqs.clone(), (literal!("\n\t")).clone())?;
            println!("{}", (literal!("\n")).clone());
            dumpVarLst(colVars.clone(), ({ let mut __mm_s = String::new(); __mm_s.push_str(&*literal!("columnVars(")); __mm_s.push_str(&*intString((colVars.clone().len() as i32))); __mm_s.push_str(&*literal!(")")); ArcStr::from(__mm_s) }).clone())?;
            ()
        },
        None => {
            ()
        },
        _ => unreachable!("match_deref! exhaustiveness placeholder"),
    } });
    Ok(())
}

fn extObjInfoString(mut info: SimCode::ExtObjInfo) -> Result<()> {
    let mut vars: Arc<metamodelica::List<SimCodeVar::SimVar>> = metamodelica::nil();
    let mut aliases: Arc<metamodelica::List<(Arc<DAE::ComponentRef>, Arc<DAE::ComponentRef>)>> = metamodelica::nil();
    let mut cr1: Arc<DAE::ComponentRef> = Arc::new(DAE::ComponentRef::WILD);
    let mut cr2: Arc<DAE::ComponentRef> = Arc::new(DAE::ComponentRef::WILD);
    let SimCode::EXTOBJINFO { aliases: __pa0, vars: __pa1 } = (info.clone()) else { bail!("pattern mismatch") };
    aliases = __pa0.clone();
    vars = __pa1.clone();
    dumpVarLst(vars.clone(), (literal!("external object info")).clone())?;
    if !(aliases.clone().is_empty()) {
        println!("{}", ({ let mut __mm_s = String::new(); __mm_s.push_str(&*literal!("external object aliase (")); __mm_s.push_str(&*intString((aliases.clone().len() as i32))); __mm_s.push_str(&*literal!(")")); ArcStr::from(__mm_s) }).clone());
        for mut tpl in &*aliases.clone() {
            let mut tpl = tpl.clone();
            (cr1, cr2) = tpl.clone();
            println!("{}", ({ let mut __mm_s = String::new(); __mm_s.push_str(&*ComponentReference::crefStr(cr1.clone())?); __mm_s.push_str(&*literal!(" = ")); __mm_s.push_str(&*ComponentReference::crefStr(cr2.clone())?); ArcStr::from(__mm_s) }).clone());
        }
        println!("{}", (literal!("\n")).clone());
    }
    Ok(())
}

