    let mut outFMIIndex: i32 = 0;
    let (__pa0, (__pa1, __pa2)) = List::mapFold(inVars.clone(), Arc::new(setVariableIndexHelper2), (inIndex.clone(), inFMIIndex.clone()));
    outVars = __pa0.clone();
