                    let mut displayUnitStr: ArcStr = displayUnitStr.clone();
                    unitStr = (extractVarUnitStr(uexp.clone())?).clone();
                    displayUnitStr = (extractVarUnitStr(duexp.clone())?).clone();
                    Ok((unitStr.clone(), displayUnitStr.clone()))
