fn isInitialExact(mut initial_: SimCodeVar::Initial) -> bool {
    let mut outBoolean: bool = false;
    outBoolean = (match initial_.clone() {
        SimCodeVar::Initial::EXACT => true,
        _ => false,
    });
    outBoolean
}

