// NOTE: #[tailcall::tailcall] disabled: function body contains a `match_deref!{…}` match,
// and the tailcall rewriter cannot see arms hidden behind the macro's `Deref @` patterns.
fn translateSparsePatterInts2FMIUnknown(mut inSparsePattern: Arc<metamodelica::List<(i32, Arc<metamodelica::List<i32>>)>>, mut inAccum: Arc<metamodelica::List<SimCode::FmiUnknown>>) -> Result<Arc<metamodelica::List<SimCode::FmiUnknown>>> {
    let mut outFmiUnknown: Arc<metamodelica::List<SimCode::FmiUnknown>> = metamodelica::nil();
    outFmiUnknown = (::match_deref::match_deref! { match &((inSparsePattern.clone(), inAccum.clone())) {
        (Deref @ metamodelica::List::Nil, _) => {
            inAccum.clone().reverse()
        },
        (Deref @ metamodelica::List::Cons { head: (unknown, dependencies), tail: rest }, _) => {
            let mut dependenciesKind: Arc<metamodelica::List<ArcStr>> = metamodelica::nil();
            dependenciesKind = List::fill((literal!("dependent")).clone(), (dependencies.clone().len() as i32));
            translateSparsePatterInts2FMIUnknown(rest.clone(), cons(SimCode::FmiUnknown { index: unknown.clone(), dependencies: dependencies.clone(), dependenciesKind: dependenciesKind.clone() }, inAccum.clone()))?
        },
        _ => bail!("match: no arm matched"),
    } });
    Ok(outFmiUnknown)
}

fn translateSparsePatterCref2DerCref(mut sparsePattern: Arc<metamodelica::List<(Arc<DAE::ComponentRef>, Arc<metamodelica::List<Arc<DAE::ComponentRef>>>)>>, mut inSimVarHT: (metamodelica::Array<Arc<metamodelica::List<(Arc<DAE::ComponentRef>, i32)>>>, (i32, i32, metamodelica::Array<Option<(Arc<DAE::ComponentRef>, SimCodeVar::SimVar)>>), i32, (HashTableCrefSimVar::FuncHashCref, HashTableCrefSimVar::FuncCrefEqual, HashTableCrefSimVar::FuncCrefStr, HashTableCrefSimVar::FuncExpStr)), mut inAccum: Arc<metamodelica::List<(Arc<DAE::ComponentRef>, Arc<metamodelica::List<Arc<DAE::ComponentRef>>>)>>, mut inAccum2: Arc<metamodelica::List<Arc<DAE::ComponentRef>>>) -> Result<(Arc<metamodelica::List<(Arc<DAE::ComponentRef>, Arc<metamodelica::List<Arc<DAE::ComponentRef>>>)>>, Arc<metamodelica::List<Arc<DAE::ComponentRef>>>)> {
    let mut outSparsePattern: Arc<metamodelica::List<(Arc<DAE::ComponentRef>, Arc<metamodelica::List<Arc<DAE::ComponentRef>>>)>> = metamodelica::nil();
    let mut outDerCrefs: Arc<metamodelica::List<Arc<DAE::ComponentRef>>> = metamodelica::nil();
    (outSparsePattern, outDerCrefs) = (::match_deref::match_deref! { match &(sparsePattern.clone()) {
        Deref @ metamodelica::List::Nil => {
            (inAccum.clone().reverse(), inAccum2.clone().reverse())
        },
        Deref @ metamodelica::List::Cons { head: (cref, crefs), tail: rest } => {
            let mut simVar: SimCodeVar::SimVar;
            let mut cref = (*cref).clone();
            simVar = BaseHashTable::get(cref.clone(), inSimVarHT.clone())?;
            if BackendVariable::isVarKindState(simVar.varKind.clone()) {
                cref = ComponentReference::crefPrefixDer(cref.clone());
            }
            translateSparsePatterCref2DerCref(rest.clone(), inSimVarHT.clone(), cons((cref.clone(), crefs.clone()), inAccum.clone()), cons(cref.clone(), inAccum2.clone()))?
        },
        _ => unreachable!("match_deref! exhaustiveness placeholder"),
    } });
    Ok((outSparsePattern, outDerCrefs))
}

// NOTE: #[tailcall::tailcall] disabled: function body contains a `match_deref!{…}` match,
// and the tailcall rewriter cannot see arms hidden behind the macro's `Deref @` patterns.
fn mergeSparsePatter(mut inA: Arc<metamodelica::List<(Arc<DAE::ComponentRef>, Arc<metamodelica::List<Arc<DAE::ComponentRef>>>)>>, mut inB: Arc<metamodelica::List<(Arc<DAE::ComponentRef>, Arc<metamodelica::List<Arc<DAE::ComponentRef>>>)>>, mut inAccum: Arc<metamodelica::List<(Arc<DAE::ComponentRef>, Arc<metamodelica::List<Arc<DAE::ComponentRef>>>)>>) -> Result<Arc<metamodelica::List<(Arc<DAE::ComponentRef>, Arc<metamodelica::List<Arc<DAE::ComponentRef>>>)>>> {
    let mut out: Arc<metamodelica::List<(Arc<DAE::ComponentRef>, Arc<metamodelica::List<Arc<DAE::ComponentRef>>>)>> = metamodelica::nil();
    out = (::match_deref::match_deref! { match &((inA.clone(), inB.clone(), inAccum.clone())) {
        (Deref @ metamodelica::List::Nil, Deref @ metamodelica::List::Nil, _) => {
            inAccum.clone().reverse()
        },
        (Deref @ metamodelica::List::Nil, _, _) => {
            inB.clone()
        },
        (_, Deref @ metamodelica::List::Nil, _) => {
            inA.clone()
        },
        (Deref @ metamodelica::List::Cons { head: (crefA, listA), tail: restA }, Deref @ metamodelica::List::Cons { head: (crefB, listB), tail: restB }, _) => {
            let mut listOut: Arc<metamodelica::List<Arc<DAE::ComponentRef>>> = metamodelica::nil();
            let true = (ComponentReferenceBasics::crefEqual(crefA.clone(), crefB.clone())?) else { bail!("pattern mismatch") };
            listOut = List::unionOnTrue(listA.clone(), listB.clone(), Arc::new(ComponentReferenceBasics::crefEqual));
            mergeSparsePatter(restA.clone(), restB.clone(), cons((crefA.clone(), listOut.clone()), inAccum.clone()))?
        },
        _ => bail!("match: no arm matched"),
    } });
    Ok(out)
}

pub fn getStateSimVarIndexFromIndex(mut inStateVars: Arc<metamodelica::List<SimCodeVar::SimVar>>, mut inIndex: i32) -> Result<i32> {
    let mut outVariableIndex: i32 = 0;
    let mut stateVar: SimCodeVar::SimVar;
    stateVar = (inStateVars.clone()).get(inIndex.clone() + 1 - if (Config::simCodeTarget()? == literal!("Cpp")) {0} else {(inStateVars.clone().len() as i32)})?;
    outVariableIndex = getVariableIndex(stateVar.clone());
    Ok(outVariableIndex)
}

fn getNumScalars(mut vars: Arc<metamodelica::List<SimCodeVar::SimVar>>) -> i32 {
    let mut numScalars: i32 = 0;
    numScalars = List::applyAndFold(vars.clone(), Arc::new(fnptr!(intAdd, i32, i32)), Arc::new(getNumElems), 0);
    numScalars
}

fn getNumElems(mut var: SimCodeVar::SimVar) -> Result<i32> {
    let mut numElems: i32 = 0;
    numElems = (::match_deref::match_deref! { match &(var.clone()) {
        SimCodeVar::SimVar { type_: Deref @ DAE::Type::T_ARRAY { .. }, .. } => {
            numElems = 1;
            for mut d in &*var.numArrayElement.clone() {
                let mut d = d.clone();
                numElems = numElems.clone() * stringInt((d.clone()).clone())?;
            }
            numElems.clone()
        },
        _ => 1,
        _ => unreachable!("match_deref! exhaustiveness placeholder"),
    } });
    Ok(numElems)
}

pub fn getScalarElements(mut var: SimCodeVar::SimVar) -> Result<Arc<metamodelica::List<SimCodeVar::SimVar>>> {
    let mut elts: Arc<metamodelica::List<SimCodeVar::SimVar>> = metamodelica::nil();
    let mut dims: Arc<metamodelica::List<i32>> = metamodelica::nil();
    let mut elt: SimCodeVar::SimVar;
    let mut index: i32 = 0;
    let mut fmi_index: i32 = 0;
    elts = (::match_deref::match_deref! { match &(var.clone()) {
        SimCodeVar::SimVar { exportVar: None, type_: Deref @ DAE::Type::T_ARRAY { .. }, .. } => metamodelica::nil(),
        SimCodeVar::SimVar { fmi_index: Some(fmi_index), variable_index: Some(index), type_: Deref @ DAE::Type::T_ARRAY { .. }, .. } => {
            dims = List::map(List::lastN(var.numArrayElement.clone(), (var.numArrayElement.clone().len() as i32))?, Arc::new(stringInt));
            elt = var.clone();
            elt.type_ = Types::arrayElementType(var.type_.clone());
            elts = fillScalarElements(elt.clone(), dims.clone(), 1, metamodelica::nil(), metamodelica::nil())?;
            (elts, _, _) = setVariableIndexHelper(elts.clone(), index.clone(), fmi_index.clone());
            elts.clone()
        },
        _ => list![var.clone()],
        _ => unreachable!("match_deref! exhaustiveness placeholder"),
    } });
    Ok(elts)
}

fn fillScalarElements(mut eltIn: SimCodeVar::SimVar, mut dims: Arc<metamodelica::List<i32>>, mut dimIdx: i32, mut subsIn: Arc<metamodelica::List<Arc<DAE::Subscript>>>, mut elts: Arc<metamodelica::List<SimCodeVar::SimVar>>) -> Result<Arc<metamodelica::List<SimCodeVar::SimVar>>> {
    let mut elts: Arc<metamodelica::List<SimCodeVar::SimVar>> = elts;
    let mut elt: SimCodeVar::SimVar = eltIn.clone();
    let mut subs: Arc<metamodelica::List<Arc<DAE::Subscript>>> = metamodelica::nil();
    for mut i in (1..=(dims.clone()).get(dimIdx.clone())?).rev() {
        subs = cons(Arc::new(DAE::Subscript::INDEX { exp: Arc::new(DAE::Exp::ICONST { integer: i.clone() }) }), subsIn.clone());
        if dimIdx.clone() < (dims.clone().len() as i32) {
            elts = fillScalarElements(eltIn.clone(), dims.clone(), dimIdx.clone() + 1, subs.clone(), elts.clone())?;
        } else {
            subs = subs.clone().reverse();
            elt.name = ComponentReference::crefSetLastSubs(elt.name.clone(), subs.clone())?;
            elt.exportVar = Some(ComponentReference::crefSetLastSubs(Util::getOption(elt.exportVar.clone())?, subs.clone())?);
            let _ = (match elt.clone() {
        SimCodeVar::SimVar { varKind: BackendDAE::VarKind::CLOCKED_STATE { isStartFixed: mut fixed, previousName: ref cref }, .. } => {
            elt.varKind = BackendDAE::VarKind::CLOCKED_STATE { previousName: ComponentReference::crefSetLastSubs(cref.clone(), subs.clone())?, isStartFixed: fixed.clone() };
            ()
        },
        _ => {
            ()
        },
    });
            elts = cons(elt.clone(), elts.clone());
        }
    }
    Ok(elts)
}

fn getScalarVars(mut inVars: Arc<metamodelica::List<SimCodeVar::SimVar>>) -> Result<Arc<metamodelica::List<SimCodeVar::SimVar>>> {
    let mut outVars: Arc<metamodelica::List<SimCodeVar::SimVar>> = metamodelica::nil();
    outVars = metamodelica::nil();
    for mut var in &*inVars.clone().reverse() {
        let mut var = var.clone();
        outVars = listAppend(getScalarElements(var.clone())?, outVars.clone());
    }
    Ok(outVars)
}

