pub fn getValueReference(mut inSimVar: SimCodeVar::SimVar, mut inSimCode: SimCode::SimCode, mut inElimNegAliases: bool) -> Result<ArcStr> {
    let mut outValueReference: ArcStr = arcstr::literal!("");
    outValueReference = ((match (inSimVar.clone(), inElimNegAliases.clone(), Config::simCodeTarget()?) {
        (SimCodeVar::SimVar { aliasvar: SimCodeVar::AliasVariable::NEGATEDALIAS { varName: _ }, .. }, false, _) => {
            getDefaultValueReference(inSimVar.clone(), inSimCode.modelInfo.varInfo.clone())?
        },
        (_, _, _) if (stringEqual((Config::simCodeTarget()?).clone(), (literal!("Cpp")).clone()) || stringEqual((Config::simCodeTarget()?).clone(), (literal!("omsic")).clone())) => {
            let mut simVar: SimCodeVar::SimVar;
            let mut cref: Arc<DAE::ComponentRef> = Arc::new(DAE::ComponentRef::WILD);
            let mut valueReference: ArcStr = arcstr::literal!("");
            simVar = (::match_deref::match_deref! { match &(inSimVar.clone()) {
        SimCodeVar::SimVar { aliasvar: SimCodeVar::AliasVariable::ALIAS { varName: cref }, .. } => {
            cref2simvar(cref.clone(), inSimCode.clone())?
        },
        SimCodeVar::SimVar { aliasvar: SimCodeVar::AliasVariable::NEGATEDALIAS { varName: cref }, .. } => {
            cref2simvar(cref.clone(), inSimCode.clone())?
        },
        SimCodeVar::SimVar { name: Deref @ DAE::ComponentRef::CREF_QUAL { componentRef, ident: DAE::preNamePrefix, .. }, .. } => {
            cref2simvar(componentRef.clone(), inSimCode.clone())?
        },
        _ => {
            inSimVar.clone()
        },
        _ => unreachable!("match_deref! exhaustiveness placeholder"),
    } });
            valueReference = (getVarIndexByMapping(inSimCode.varToArrayIndexMapping.clone(), simVar.name.clone(), true, (literal!("-1")).clone())?).clone();
            if stringEqual((valueReference.clone()).clone(), (literal!("-1")).clone()) {
                Error::addInternalError(({ let mut __mm_s = String::new(); __mm_s.push_str(&*literal!("invalid return value from getVarIndexByMapping for ")); __mm_s.push_str(&*simVarString(simVar.clone())?); ArcStr::from(__mm_s) }).clone(), metamodelica::sourceInfo!())?;
            }
            valueReference.clone()
        },
        (SimCodeVar::SimVar { aliasvar: SimCodeVar::AliasVariable::ALIAS { varName: ref cref }, .. }, _, _) => {
            getDefaultValueReference(cref2simvar(cref.clone(), inSimCode.clone())?, inSimCode.modelInfo.varInfo.clone())?
        },
        _ => {
            getDefaultValueReference(inSimVar.clone(), inSimCode.modelInfo.varInfo.clone())?
        },
    })).clone();
    Ok(outValueReference)
}

fn getDefaultValueReference(mut inSimVar: SimCodeVar::SimVar, mut inVarInfo: SimCode::VarInfo) -> Result<ArcStr> {
    let mut outDefaultValueReference: ArcStr = arcstr::literal!("");
    let mut reference: i32 = 0;
    let mut numReal: i32 = 2 * inVarInfo.numStateVars.clone() + inVarInfo.numAlgVars.clone() + inVarInfo.numDiscreteReal.clone() + inVarInfo.numParams.clone() + inVarInfo.numAlgAliasVars.clone();
    let mut numInteger: i32 = inVarInfo.numIntAlgVars.clone() + inVarInfo.numIntParams.clone() + inVarInfo.numIntAliasVars.clone();
    let mut numBoolean: i32 = inVarInfo.numBoolAlgVars.clone() + inVarInfo.numBoolParams.clone() + inVarInfo.numBoolAliasVars.clone();
    reference = getVariableIndex(inSimVar.clone());
    if reference.clone() > numReal.clone() + numInteger.clone() + numBoolean.clone() {
        reference = reference.clone() - numReal.clone() - numInteger.clone() - numBoolean.clone();
    } else if reference.clone() > numReal.clone() + numInteger.clone() {
        reference = reference.clone() - numReal.clone() - numInteger.clone();
    } else if reference.clone() > numReal.clone() {
        reference = reference.clone() - numReal.clone();
    } else if reference.clone() < 0 {
        Error::addInternalError((literal!("invalid return value from getVariableIndex")).clone(), metamodelica::sourceInfo!())?;
    }
    outDefaultValueReference = ArcStr::from(::std::format!("{}", reference.clone() - 1));
    Ok(outDefaultValueReference)
}

pub fn getLocalValueReference(mut inSimVar: SimCodeVar::SimVar, mut inSimCode: SimCode::SimCode, mut inCrefToSimVarHT: (metamodelica::Array<Arc<metamodelica::List<(Arc<DAE::ComponentRef>, i32)>>>, (i32, i32, metamodelica::Array<Option<(Arc<DAE::ComponentRef>, SimCodeVar::SimVar)>>), i32, (HashTableCrefSimVar::FuncHashCref, HashTableCrefSimVar::FuncCrefEqual, HashTableCrefSimVar::FuncCrefStr, HashTableCrefSimVar::FuncExpStr)), mut inElimNegAliases: bool) -> Result<ArcStr> {
    let mut outValueReference: ArcStr = arcstr::literal!("");
    outValueReference = ('mc: {
        let __mc_input = (inSimVar.clone(), inElimNegAliases.clone(), inCrefToSimVarHT.clone());
        if let Ok(__v) = (|| -> Result<_> {
            let (SimCodeVar::SimVar { name: ref cref, .. }, _, mut crefToSimVarHT) = __mc_input.clone() else { bail!("nomatch") };
            let mut valueReference: ArcStr = arcstr::literal!("");
            valueReference = (localCref2Index(cref.clone(), crefToSimVarHT.clone())?).clone();
            if stringEqual((valueReference.clone()).clone(), (literal!("-1")).clone()) {
                valueReference = (getValueReference(inSimVar.clone(), inSimCode.clone(), inElimNegAliases.clone())?).clone();
            }
            Ok(valueReference.clone())
        })() { break 'mc __v; }
        if let Ok(__v) = (|| -> Result<_> {
            let _ = __mc_input.clone() else { bail!("nomatch") };
            Error::addInternalError((literal!("getLocalValueReference failed.")).clone(), metamodelica::sourceInfo!())?;
            Ok(literal!("ERROR: getLocalValueReference failed"))
        })() { break 'mc __v; }
        bail!("matchcontinue: no arm matched")
    }).clone();
    Ok(outValueReference)
}

fn getHighestDerivation(mut inDAE: Arc<BackendDAE::BackendDAE>) -> Result<i32> {
    let mut highestDerivation: i32 = 0;
    let mut vars: Arc<metamodelica::List<BackendDAE::Var>> = metamodelica::nil();
    let mut states: Arc<metamodelica::List<BackendDAE::Var>> = metamodelica::nil();
    let mut idcs: Arc<metamodelica::List<i32>> = metamodelica::nil();
    let mut ders: metamodelica::Array<i32>;
    let mut depth: metamodelica::Array<i32>;
    let mut allStates: BackendDAE::Variables;
    let mut var: BackendDAE::Var;
    let mut index: i32 = 0;
    let mut pos: i32 = 0;
    let mut length: i32 = 0;
    let mut curIndex: i32 = 0;
    let mut derCref: Arc<DAE::ComponentRef> = Arc::new(DAE::ComponentRef::WILD);
    vars = BackendDAEUtil::getAllVarLst(inDAE.clone())?;
    states = List::filterOnTrue(vars.clone(), Arc::new(fnptr!(BackendVariable::isStateVar, BackendDAE::Var)));
    length = (states.clone().len() as i32);
    if length.clone() == 0 {
        highestDerivation = 0;
        return Ok(highestDerivation);
    }
    ders = arrayCreate(length.clone(), -1);
    depth = arrayCreate(length.clone(), -1);
    allStates = BackendVariable::listVar1(states.clone());
    curIndex = 1;
    for mut state in &*states.clone() {
        let mut state = state.clone();
        let _ = 'mc: {
        let __mc_input = state.clone();
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                BackendDAE::Var { varKind: BackendDAE::VarKind::STATE { derName: Some(derCref), index, .. }, .. } => {
                    let mut var: BackendDAE::Var;
                    let mut pos: i32 = pos.clone();
                    (var, pos) = BackendVariable::getVarSingle(derCref.clone(), allStates.clone())?;
                    if !(BackendVariable::varEqual(state.clone(), var.clone())) {
                        {let _arr = ders.clone(); _arr.borrow_mut()[(curIndex.clone()-1) as usize] = pos.clone(); _arr};
                    } else {
                        {let _arr = depth.clone(); _arr.borrow_mut()[(curIndex.clone()-1) as usize] = 0; _arr};
                    }
                    Ok(())
                }
                _ => bail!("nomatch"),
            }}
        })() { break 'mc __v; }
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                BackendDAE::Var { .. } => {
                    {let _arr = depth.clone(); _arr.borrow_mut()[(curIndex.clone()-1) as usize] = 0; _arr};
                    Ok(())
                }
                _ => bail!("nomatch"),
            }}
        })() { break 'mc __v; }
        bail!("matchcontinue: no arm matched")
    };
        curIndex = curIndex.clone() + 1;
    }
    for mut i in 1..=length.clone() {
        getHighestDerivationVisit(i.clone(), ders.clone(), depth.clone())?;
    }
    highestDerivation = {
        let mut __acc: Option<i32> = None;
        for mut i in (depth.clone()).borrow().iter() {
            let __x = i.clone();
            __acc = Some(match __acc { None => __x, Some(__cur) => if __x > __cur { __x } else { __cur } });
        }
        __acc.ok_or_else(|| anyhow::anyhow!("empty max reduction"))?
    };
    GCExt::free(ders.clone());
    GCExt::free(depth.clone());
    Ok(highestDerivation)
}

fn getHighestDerivationVisit(mut i: i32, mut ders: metamodelica::Array<i32>, mut depth: metamodelica::Array<i32>) -> Result<i32> {
    let mut d: i32 = depth.clone().borrow()[(i.clone()-1) as usize].clone();
    if d.clone() >= 0 {
        return Ok(d);
    } else if d.clone() == -2 {
        d = 0;
        return Ok(d);
    }
    {let _arr = depth.clone(); _arr.borrow_mut()[(i.clone()-1) as usize] = -2; _arr};
    d = getHighestDerivationVisit(ders.clone().borrow()[(i.clone()-1) as usize].clone(), ders.clone(), depth.clone())?;
    {let _arr = depth.clone(); _arr.borrow_mut()[(i.clone()-1) as usize] = d.clone(); _arr};
    Ok(d)
}

fn hasLargeEquationSystems(mut iDlow: Arc<BackendDAE::BackendDAE>, mut iInitDAE: Arc<BackendDAE::BackendDAE>) -> Result<bool> {
    let mut oHasLargeEqSystem: bool = false;
    let mut hasLargeEqSystem: bool = false;
    let mut eqs: Arc<metamodelica::List<Arc<BackendDAE::EqSystem>>> = metamodelica::nil();
    let __pa0 = ::match_deref::match_deref! { match &(iDlow.clone()) {
        Deref @ DAE { eqs: __pa0, .. } => __pa0.clone(),
        _ => bail!("pattern mismatch"),
    } };
    eqs = __pa0.clone();
    for mut eqsys in &*eqs.clone() {
        let mut eqsys = eqsys.clone();
        if boolNot(hasLargeEqSystem.clone()) {
            hasLargeEqSystem = hasLargeEquationSystems1(BackendDAEUtil::getStrongComponents(eqsys.clone()))?;
        }
    }
    if boolNot(hasLargeEqSystem.clone()) {
        let __pa1 = ::match_deref::match_deref! { match &(iInitDAE.clone()) {
            Deref @ DAE { eqs: __pa1, .. } => __pa1.clone(),
            _ => bail!("pattern mismatch"),
        } };
        eqs = __pa1.clone();
        for mut eqsys in &*eqs.clone() {
            let mut eqsys = eqsys.clone();
            if boolNot(hasLargeEqSystem.clone()) {
                hasLargeEqSystem = hasLargeEquationSystems1(BackendDAEUtil::getStrongComponents(eqsys.clone()))?;
            }
        }
    }
    if Flags::isSet(Flags::DUMP_DGESV.clone())? {
        if boolNot(hasLargeEqSystem.clone()) {
            println!("{}", (literal!("This model has no large linear or nonlinear equation system, thus the use of dgesv (OMCompiler/3rdParty/) is prefered.\n")).clone());
        } else {
            println!("{}", (literal!("This model has at least one large or nonlinear linear equation system, thus the use of Lapack is prefered.\n")).clone());
        }
    }
    oHasLargeEqSystem = hasLargeEqSystem.clone();
    Ok(oHasLargeEqSystem)
}

fn hasLargeEquationSystems1(mut iComps: Arc<metamodelica::List<Arc<BackendDAE::StrongComponent>>>) -> Result<bool> {
    let mut oHasLargeEquationSystems: bool = false;
    let mut hasLargeEqSystem: bool = false;
    let mut vars: Arc<metamodelica::List<i32>> = metamodelica::nil();
    for mut comp in &*iComps.clone() {
        let mut comp = comp.clone();
        if boolNot(hasLargeEqSystem.clone()) {
            if boolOr(BackendDAEUtil::isLinearEqSystemComp(comp.clone()), BackendDAEUtil::isNonLinearEqSystemComp(comp.clone())) {
                let __pa0 = ::match_deref::match_deref! { match &(comp.clone()) {
                    Deref @ BackendDAE::StrongComponent::EQUATIONSYSTEM { vars: __pa0, .. } => __pa0.clone(),
                    _ => bail!("pattern mismatch"),
                } };
                vars = __pa0.clone();
                hasLargeEqSystem = intGt((vars.clone().len() as i32), 10);
            } else {
                if boolOr(BackendDAEUtil::isLinearTornSystemComp(comp.clone()), BackendDAEUtil::isNonLinearTornSystemComp(comp.clone())) {
                    let __pa1 = ::match_deref::match_deref! { match &(comp.clone()) {
                        Deref @ BackendDAE::StrongComponent::TORNSYSTEM { strictTearingSet: BackendDAE::TearingSet { tearingvars: __pa1, .. }, .. } => __pa1.clone(),
                        _ => bail!("pattern mismatch"),
                    } };
                    vars = __pa1.clone();
                    hasLargeEqSystem = intGt((vars.clone().len() as i32), 10);
                }
            }
        }
    }
    oHasLargeEquationSystems = hasLargeEqSystem.clone();
    Ok(oHasLargeEquationSystems)
}

fn createSimVarsForSensitivities(mut inStateSimVars: Arc<metamodelica::List<SimCodeVar::SimVar>>, mut inParamSimVars: Arc<metamodelica::List<SimCodeVar::SimVar>>, mut nFixedParameters: i32) -> Result<(Arc<metamodelica::List<SimCodeVar::SimVar>>, i32)> {
    let mut outSimCodeVars: Arc<metamodelica::List<SimCodeVar::SimVar>> = metamodelica::nil();
    let mut countSensitivityParams: i32 = 0;
    let debug: bool = false;
    let mut tmpVariables: BackendDAE::Variables;
    let mut emptyVars: BackendDAE::Variables;
    let mut var: BackendDAE::Var;
    let mut i: i32 = 0;
    let mut cref: Arc<DAE::ComponentRef> = Arc::new(DAE::ComponentRef::WILD);
    let mut sensitivityParams: Arc<metamodelica::List<SimCodeVar::SimVar>> = metamodelica::nil();
    emptyVars = BackendVariable::emptyVars(BaseHashTable::bigBucketSize.clone());
    tmpVariables = BackendVariable::emptyVarsSized((inStateSimVars.clone().len() as i32) * nFixedParameters.clone());
    for mut param in &*inParamSimVars.clone() {
        let mut param = param.clone();
        if param.isValueChangeable.clone() && ComponentReference::crefIsIdent(param.name.clone()) {
            countSensitivityParams = countSensitivityParams.clone() + 1;
            sensitivityParams = cons(param.clone(), sensitivityParams.clone());
            for mut state in &*inStateSimVars.clone() {
                let mut state = state.clone();
                cref = ComponentReferenceBasics::makeCrefIdent((literal!("$Sensitivities")).clone(), DAE::T_REAL_DEFAULT.clone(), metamodelica::nil());
                cref = ComponentReference::joinCrefs(cref.clone(), param.name.clone())?;
                cref = ComponentReference::joinCrefs(cref.clone(), state.name.clone())?;
                if debug.clone() {
                    println!("{}", ({ let mut __mm_s = String::new(); __mm_s.push_str(&*literal!("createSimVarsForSensitivities for Var: ")); __mm_s.push_str(&*ComponentReference::crefStr(cref.clone())?); __mm_s.push_str(&*literal!("\n")); ArcStr::from(__mm_s) }).clone());
                }
                var = BackendVariable::makeVar(cref.clone());
                tmpVariables = BackendVariable::addNewVar(var.clone(), tmpVariables.clone())?;
            }
        }
    }
    (outSimCodeVars, _) = BackendVariable::traverseBackendDAEVars(tmpVariables.clone(), Arc::new(traversingdlowvarToSimvar), (metamodelica::nil(), emptyVars.clone()))?;
    outSimCodeVars = outSimCodeVars.clone().reverse();
    outSimCodeVars = listAppend(sensitivityParams.clone().reverse(), outSimCodeVars.clone());
    Ok((outSimCodeVars, countSensitivityParams))
}

